import{_ as s,l,o as e,c as o,v as i,p as S,x as t,d as p,i as I,S as n}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"IS-IS","description":"","frontmatter":{"title":"IS-IS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isis.md","filePath":"cs/isis.md","lastUpdated":1789023840000}'),P={name:"cs/isis.md"};function d(h,a,c,L,_,T){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="is-is" tabindex="-1">IS-IS <a class="header-anchor" href="#is-is" aria-label="Permalink to &quot;IS-IS&quot;">​</a></h1><div class="epigraph"><p>IS-IS 同样洪泛链路状态、同样跑 SPF，但 PDU 走链路层，层级是 L1/L2，TLV 让它后来比 OSPFv2 更容易带新地址族。</p><footer>—— 据 ISO/IEC 10589；RFC 1195 把 IS-IS 用于 IP；RFC 5308 IPv6 整理</footer></div><p><a href="/cs/ospf-areas-lsa">上一课</a> 钉死 OSPF 区域。运营商骨干常跑 IS-IS。缺口是<strong>对照</strong>：不是再学一遍 Dijkstra，而是 CLNS 出身的两级层级、LSP 与 TLV。本课不把 RIP 计时器写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OSPF 是 IP 上的协议，依赖 IP 可达来传 LSA（邻接除外）。IS-IS Hello/LSP 可直接封装在二层，地址族可后加 TLV——历史上加 IPv6、SR 比 OSPFv2 补丁轻松。L1 像非骨干区域，L2 像骨干；L1/L2 路由器相当于 ABR。度量原 6 比特，宽度量后才适合 TE。</p><p>不要把 IS-IS 写成「二层路由替代 STP」：它算的是 IP（或 CLNS）下一跳，不是 MAC 洪泛树。</p><p><span class="marginnote">ISO 10589。RFC 1195 引入 IP。DIS 类似 DR 但广播网上选出。本课不背 NET 地址编码。</span></p><h3 id="二层-pdu-仍算-ip-下一跳" tabindex="-1">二层 PDU 仍算 IP 下一跳 <a class="header-anchor" href="#二层-pdu-仍算-ip-下一跳" aria-label="Permalink to &quot;二层 PDU 仍算 IP 下一跳&quot;">​</a></h3><p>不是 STP 替代。L1/L2 对应区域分层，TLV 方便加地址族与 SID。与 OSPF 选谁是生态，SPF 同构。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表：邻接、层级、扩展性、BFD 配套。画：L1 区 → L1/L2 → L2 骨干。与 OSPF 一样可 ECMP。承载 SR 前缀 SID 是后课，这里只承认 TLV 可扩展。</p>',11)),(e(),S(n,null,{default:t(()=>[I(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22L1%20LSP%20%E5%8C%BA%E5%86%85%22%5D%20--%3E%20L12%5B%22L1%2FL2%20%E8%BE%B9%E7%95%8C%22%5D%0A%20%20L12%20--%3E%20L2%5B%22L2%20%E9%AA%A8%E5%B9%B2%22%5D%0A%20%20TLV%5B%22TLV%20%E6%89%A9%E5%B1%95%22%5D%20--%3E%20AF%5B%22IPv4%2FIPv6%2FSR%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>主干链路状态课的洪泛可靠性（序号、老化）两边同构。选择哪一个往往是运维传统与 TE/SR 生态，不是容量公式。卫星高延迟链路上 Hello 死亡计时要放宽，与介质无关的协议定时器问题。</p><p>DIS 与 OSPF DR：都是减少广播网邻接全网状，细节不同，对象同类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IS-IS 多拓扑的全部。RIP 对照是下一课。后课默认：域内链路状态有 OSPF 与 IS-IS 两套互操作栈，SPF 相同。</p><p>不要同时在同一链路上跑两套无必要的 IGP。</p><p>上一课留下的缺口在本课收口；「IS-IS」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/rip">RIP 对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IS-IS：二层 PDU、L1/L2、TLV 扩展。</li><li>计算仍是 SPF，不是距离向量。</li><li>与 OSPF 分工是工程生态，不是对错。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ISO 10589；RFC 1195；RFC 5308。</li></ul>',10))])}const f=s(P,[["render",d]]);export{m as __pageData,f as default};
